writing.exampleCode:
let values = [2, 4, 6];
std::thread::scope(|scope| {
    scope.spawn(|| {
        println!("{}", values.len());
    });
});

writing.practiceCode:
let mut values = [2, 4, 6, 8];
let (left, right) = values.split_at_mut(2);
std::thread::scope(|scope| {
    scope.spawn(|| left[0] += 1);
    scope.spawn(|| right[0] += 1);
});
println!("{values:?}");

recall.code:
let mut data = [1, 2, 3, 4];
let (left, right) = data.split_at_mut(2);
std::thread::scope(|s| {
    s.spawn(|| left.iter_mut().for_each(|x| *x *= 10));
    s.spawn(|| right.iter_mut().for_each(|x| *x += 1));
});
println!("{data:?}");

